let transactions=[],activeFilter="all";const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);const statusClass=s=>s==="متأخرة"?"late":s==="مكتملة"||s==="مغلقة"?"done":"progress",priorityClass=p=>({"منخفضة":"low","عادية":"normal","مهمة":"important","عاجلة":"urgent","حرجة":"critical"}[p]||"normal");
function toast(m,e=false){const x=$("#toast");x.textContent=m;x.style.background=e?"#8e2f2f":"#163d31";x.classList.add("show");setTimeout(()=>x.classList.remove("show"),3000)}
async function request(path,options={}){const method=options.method||"GET",start=performance.now();console.groupCollapsed(`[مراسلات API] ${method} ${path}`);console.log("الطلب",options.body||"بدون بيانات");try{const res=await fetch(path,{headers:options.body instanceof FormData?{}:{"content-type":"application/json"},...options}),data=(res.headers.get("content-type")||"").includes("json")?await res.json():await res.text();console.log("الاستجابة",{status:res.status,duration_ms:Math.round(performance.now()-start),data});console.groupEnd();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);return data}catch(e){console.error("فشل الطلب",e);console.groupEnd();toast(e.message,true);throw e}}
const sla=t=>["مكتملة","مغلقة"].includes(t.status)?"مكتملة":Math.ceil((new Date(t.due_at)-new Date())/86400000)<0?`متأخرة ${Math.abs(Math.ceil((new Date(t.due_at)-new Date())/86400000))} يوم`:`متبقي ${Math.ceil((new Date(t.due_at)-new Date())/86400000)} يوم`;
const row=t=>`<tr><td class="trx-id">${t.reference}</td><td>${t.type}</td><td><strong>${t.subject}</strong></td><td>${t.entity}</td><td><span class="priority ${priorityClass(t.priority)}">${t.priority}</span></td><td>${t.department}</td><td><span class="badge ${statusClass(t.status)}">${t.status}</span></td><td>${sla(t)}</td><td><button class="row-btn" data-id="${t.id}">←</button></td></tr>`;
function render(list=transactions){$("#allRows").innerHTML=list.map(row).join("")||'<tr><td colspan="9">لا توجد نتائج مطابقة</td></tr>';$("#urgentRows").innerHTML=list.filter(t=>!["مكتملة","مغلقة"].includes(t.status)).slice(0,4).map(t=>`<tr><td class="trx-id">${t.reference}</td><td><strong>${t.subject}</strong><small>${t.entity}</small></td><td>${t.department}</td><td>${new Date(t.created_at).toLocaleDateString("ar-SA")}</td><td><span class="badge ${statusClass(t.status)}">${t.status}</span></td><td>${sla(t)}</td><td><button class="row-btn" data-id="${t.id}">←</button></td></tr>`).join("");$$(".row-btn").forEach(b=>b.onclick=()=>openDrawer(+b.dataset.id))}
async function loadTransactions(params=""){const r=await request("/api/transactions"+params);transactions=r.data;render();const v=$$(".kpis article strong");if(v[0])v[0].textContent=transactions.filter(t=>t.type==="وارد").length;if(v[1])v[1].textContent=transactions.filter(t=>t.type==="صادر").length;if(v[2])v[2].textContent=transactions.filter(t=>t.status==="متأخرة").length}
async function openDrawer(id){const{data:t}=await request(`/api/transactions/${id}`);$("#drawerTitle").textContent=`${t.reference} — ${t.subject}`;$("#drawerBody").innerHTML=`<div class="detail-meta"><div class="meta-box"><small>الجهة</small><strong>${t.entity}</strong></div><div class="meta-box"><small>الأولوية</small><span class="priority ${priorityClass(t.priority)}">${t.priority}</span></div><div class="meta-box"><small>الإدارة الحالية</small><strong>${t.department}</strong></div><div class="meta-box"><small>الحالة</small><select id="detailStatus"><option>جديدة</option><option>قيد الإجراء</option><option>بانتظار الرد</option><option>متأخرة</option><option>مكتملة</option><option>مغلقة</option></select></div>${t.identity_number?`<div class="meta-box"><small>رقم الهوية</small><strong>${t.identity_number}</strong></div>`:""}</div>${t.delay_reason?`<div class="delay-note"><strong>سبب التعطيل:</strong> ${t.delay_reason}</div>`:""}<h3>خريطة التتبع</h3><div class="timeline">${t.events.map((e,i)=>`<div class="event ${i===t.events.length-1?"current":""}"><h4>${e.action}</h4><p>${e.details}</p><time>${new Date(e.created_at).toLocaleString("ar-SA")}</time></div>`).join("")||"<p>لم تسجل أحداث بعد.</p>"}</div><h3>الملاحظات</h3><div>${t.comments.map(c=>`<p class="meta-box"><strong>${c.body}</strong><small>${c.author}</small></p>`).join("")||"<p>لا توجد ملاحظات.</p>"}</div><div class="modal-actions"><button class="primary" id="transferAction">تحويل المعاملة</button><button class="outline" id="commentAction">إضافة ملاحظة</button><label class="outline">رفع مرفق<input hidden type="file" id="attachAction"></label></div>`;$("#detailStatus").value=t.status;$("#detailStatus").onchange=async e=>{await request(`/api/transactions/${id}`,{method:"PATCH",body:JSON.stringify({status:e.target.value})});toast("تم تحديث الحالة");await loadTransactions();openDrawer(id)};$("#transferAction").onclick=async()=>{const department=prompt("الإدارة المحال إليها:",t.department);if(!department)return;await request(`/api/transactions/${id}/transfer`,{method:"POST",body:JSON.stringify({department,note:prompt("ملاحظة التحويل:",""),sla_days:3})});toast("تم تحويل المعاملة");await loadTransactions();openDrawer(id)};$("#commentAction").onclick=async()=>{const body=prompt("اكتب الملاحظة:");if(body){await request(`/api/transactions/${id}/comments`,{method:"POST",body:JSON.stringify({body})});toast("تمت إضافة الملاحظة");openDrawer(id)}};$("#attachAction").onchange=async e=>{if(!e.target.files[0])return;const f=new FormData();f.append("file",e.target.files[0]);await request(`/api/transactions/${id}/attachments`,{method:"POST",body:f});toast("تم رفع المرفق");openDrawer(id)};$("#drawer").classList.add("open");$("#backdrop").classList.add("open")}
function closeDrawer(){$("#drawer").classList.remove("open");$("#backdrop").classList.remove("open")}const views=$$(".view");function showView(id){views.forEach(v=>v.classList.toggle("active",v.id===id));$$(".nav-item").forEach(n=>n.classList.toggle("active",n.dataset.view===id));const n=document.querySelector(`[data-view="${id}"]`);$("#pageTitle").textContent=n?n.textContent.replace(/[0-9⌂⇄↓↑▥▤⚙]/g,"").trim():id;$(".sidebar").classList.remove("open");location.hash=id}
$$("[data-view]").forEach(b=>b.onclick=()=>showView(b.dataset.view));$$("[data-open-view]").forEach(b=>b.onclick=()=>showView(b.dataset.openView));$("#menu").onclick=()=>$(".sidebar").classList.toggle("open");$("#closeDrawer").onclick=closeDrawer;$("#backdrop").onclick=closeDrawer;$("#newBtn").onclick=()=>$("#newDialog").showModal();
const newType=$("#newType"),identityField=$("#identityField"),identityNumber=$("#identityNumber");function toggleIdentity(){identityField.hidden=newType.value!=="وارد";if(identityField.hidden)identityNumber.value=""}newType.onchange=toggleIdentity;toggleIdentity();identityNumber.oninput=()=>identityNumber.value=identityNumber.value.replace(/\D/g,"").slice(0,10);$("#saveNew").onclick=async e=>{e.preventDefault();const form=$("#newDialog form");if(!form.reportValidity())return;await request("/api/transactions",{method:"POST",body:JSON.stringify({type:newType.value,priority:$("#newPriority").value,identity_number:identityNumber.value||null,subject:$("#subjectInput").value,entity:$("#entityInput").value,department:$("#departmentInput").value,sla_days:+$("#slaInput").value})});$("#newDialog").close();form.reset();toggleIdentity();toast("تم تسجيل المعاملة فعليًا");await loadTransactions();showView("transactions")};
$("#filterBtn").onclick=()=>$("#filterPanel").classList.toggle("open");$("#showLate").onclick=()=>{showView("transactions");applyFilters("late")};$$(".tabs button").forEach(b=>b.onclick=()=>{$$(".tabs button").forEach(x=>x.classList.remove("active"));b.classList.add("active");activeFilter=b.dataset.filter;applyFilters()});async function applyFilters(force){const p=new URLSearchParams(),k=force||activeFilter;if(k==="incoming")p.set("type","وارد");if(k==="outgoing")p.set("type","صادر");if(k==="late")p.set("status","متأخرة");if($("#deptFilter").value!=="all")p.set("department",$("#deptFilter").value);if($("#statusFilter").value!=="all")p.set("status",$("#statusFilter").value);if($("#priorityFilter").value!=="all")p.set("priority",$("#priorityFilter").value);await loadTransactions("?"+p)}["#deptFilter","#statusFilter","#priorityFilter"].forEach(s=>$(s).onchange=()=>applyFilters());$("#resetFilters").onclick=()=>{$("#deptFilter").value=$("#statusFilter").value=$("#priorityFilter").value="all";activeFilter="all";loadTransactions()};
let timer;$("#globalSearch").oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>loadTransactions(e.target.value.trim()?`?q=${encodeURIComponent(e.target.value.trim())}`:""),350)};$$(".report-card button").forEach((b,i)=>b.onclick=()=>i<2?location.assign("/api/reports/transactions.csv"):request("/api/metrics").then(()=>toast("تم تحديث التقرير")));$("#templates .primary").onclick=async()=>{const name=prompt("اسم القالب:"),body=prompt("محتوى القالب:");if(name&&body){await request("/api/templates",{method:"POST",body:JSON.stringify({name,body,category:"خطابات"})});toast("تم حفظ القالب")}};
const vals=[[118,72],[126,80],[109,78],[139,87],[132,91],[148,96]],months=["أبريل","مايو","يونيو","يوليو","أغسطس","سبتمبر"];$("#chart").innerHTML=vals.map((v,i)=>`<div class="bar-group"><div class="bar in" style="height:${v[0]/1.6}px"></div><div class="bar out" style="height:${v[1]/1.6}px"></div><small>${months[i]}</small></div>`).join("");const ps=[["الإدارة التنفيذية",94],["خدمات المستفيدين",88],["الموارد المالية",82],["الشراكات",76]];$("#progressList").innerHTML=ps.map(p=>`<div class="progress-item"><div class="progress-title"><span>${p[0]}</span><b>${p[1]}%</b></div><div class="track"><div class="fill ${p[1]>85?"good":""}" style="width:${p[1]}%"></div></div></div>`).join("");$("#today").textContent=new Intl.DateTimeFormat("ar-SA",{weekday:"long",year:"numeric",month:"long",day:"numeric"}).format(new Date());showView(location.hash.slice(1)||"dashboard");request("/api/health").then(()=>loadTransactions()).catch(()=>render([]));
